import { useState, useEffect } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from "recharts";
import { getMonthlySummary, getTrends, getCategoryTrends, getBudgetStatus, createTransaction } from "../services/api";
import { G } from "../App";

const CAT_COLORS = ["#00d4ff","#7c3aed","#ff4d6d","#00ff9d","#ffd60a","#ff7849","#a78bfa"];
const CATEGORIES = ["Food","Transport","Shopping","Health","Entertainment","Utilities","Other"];

function StatCard({ label, value, sub, color, icon }) {
  return (
    <div style={{ background: G.surface, border: `1px solid ${G.border}`, borderRadius: 14, padding: "20px 22px", position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 2, background: color }} />
      <div style={{ fontSize: 24, marginBottom: 8 }}>{icon}</div>
      <div style={{ color: G.muted, fontSize: 11, letterSpacing: 1.5, textTransform: "uppercase", fontWeight: 600, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 24, fontWeight: 800, color: G.text, fontFamily: G.mono }}>{value}</div>
      {sub && <div style={{ color: G.muted, fontSize: 12, marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

const fmt = n => `₹${Number(n || 0).toLocaleString("en-IN")}`;
const now = new Date();

export default function Dashboard() {
  const [summary, setSummary]   = useState(null);
  const [trends, setTrends]     = useState([]);
  const [catData, setCatData]   = useState([]);
  const [budgets, setBudgets]   = useState([]);
  const [form, setForm]         = useState({ description: "", amount: "", category: "Food", type: "expense", date: now.toISOString().split("T")[0] });
  const [saving, setSaving]     = useState(false);
  const [msg, setMsg]           = useState("");

  const month = now.getMonth() + 1;
  const year  = now.getFullYear();

  const load = () => {
    getMonthlySummary({ month, year }).then(r => setSummary(r.data)).catch(() => {});
    getTrends({ months: 6 }).then(r => setTrends(r.data.trends || [])).catch(() => {});
    getCategoryTrends({ month, year }).then(r => setCatData(r.data.categories || [])).catch(() => {});
    getBudgetStatus({ month, year }).then(r => setBudgets(r.data.budgets || [])).catch(() => {});
  };

  useEffect(() => { load(); }, []);

  const addTxn = async () => {
    if (!form.description || !form.amount) return;
    setSaving(true);
    try {
      await createTransaction({ ...form, amount: parseFloat(form.amount), date: new Date(form.date).toISOString() });
      setMsg("✅ Added!"); setForm(f => ({ ...f, description: "", amount: "" }));
      load();
      setTimeout(() => setMsg(""), 2000);
    } catch (e) { setMsg("❌ " + (e.response?.data?.detail || "Error")); }
    setSaving(false);
  };

  const overallBudget = budgets.find(b => b.category === "Overall");
  const budgetPct = overallBudget ? Math.round((overallBudget.spent / overallBudget.limit) * 100) : 0;

  const s = {
    page: { animation: "fadeIn 0.3s ease" },
    header: { marginBottom: 28 },
    title: { fontSize: 26, fontWeight: 800, letterSpacing: "-0.5px", marginBottom: 4 },
    sub: { color: G.muted, fontSize: 13 },
    grid4: { display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14, marginBottom: 20 },
    grid2: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 20 },
    card: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 14, padding: 22 },
    cardTitle: { fontSize: 13, fontWeight: 700, color: G.text, marginBottom: 16, display: "flex", alignItems: "center", gap: 8 },
    input: { background: `${G.border}50`, border: `1px solid ${G.border}`, borderRadius: 8, padding: "9px 12px", color: G.text, fontSize: 13, fontFamily: G.font, width: "100%" },
    select: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 8, padding: "9px 12px", color: G.text, fontSize: 13, fontFamily: G.font, width: "100%" },
    addBtn: { background: `linear-gradient(135deg, ${G.accent}cc, ${G.accent2})`, border: "none", borderRadius: 8, padding: "9px 22px", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font, whiteSpace: "nowrap" },
  };

  const tooltipStyle = { contentStyle: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 8, color: G.text, fontFamily: G.font, fontSize: 12 } };

  return (
    <div style={s.page}>
      <div style={s.header}>
        <div style={s.title}>Dashboard</div>
        <div style={s.sub}>{now.toLocaleString("default", { month: "long", year: "numeric" })}</div>
      </div>

      {/* Stat cards */}
      <div style={s.grid4}>
        <StatCard label="Expenses" value={fmt(summary?.total_expenses)} sub={`${budgetPct}% of budget`} color={G.red} icon="💸" />
        <StatCard label="Income" value={fmt(summary?.total_income)} sub="This month" color={G.green} icon="💰" />
        <StatCard label="Savings" value={fmt(summary?.net_savings)} sub="Net balance" color={G.yellow} icon="🏦" />
        <StatCard label="Budget Used" value={`${budgetPct}%`} sub={overallBudget ? `of ${fmt(overallBudget.limit)}` : "No budget set"} color={G.accent} icon="🎯" />
      </div>

      {/* Budget progress */}
      {overallBudget && (
        <div style={{ ...s.card, marginBottom: 20 }}>
          <div style={s.cardTitle}>🎯 Monthly Budget Progress</div>
          <div style={{ background: G.border, borderRadius: 99, height: 10, overflow: "hidden", marginBottom: 8 }}>
            <div style={{ width: `${Math.min(budgetPct, 100)}%`, height: "100%", background: budgetPct >= 100 ? G.red : budgetPct >= 80 ? G.yellow : G.accent, borderRadius: 99, transition: "width 0.6s" }} />
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: G.muted }}>
            <span>{fmt(overallBudget.spent)} spent</span>
            <span>{fmt(overallBudget.remaining)} remaining</span>
          </div>
        </div>
      )}

      {/* Charts */}
      <div style={s.grid2}>
        <div style={s.card}>
          <div style={s.cardTitle}>📊 6-Month Trend</div>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={trends}>
              <CartesianGrid strokeDasharray="3 3" stroke={G.border} />
              <XAxis dataKey="month" tick={{ fill: G.muted, fontSize: 11 }} />
              <YAxis tick={{ fill: G.muted, fontSize: 10 }} tickFormatter={v => `₹${(v/1000).toFixed(0)}k`} />
              <Tooltip {...tooltipStyle} formatter={v => fmt(v)} />
              <Bar dataKey="expenses" fill={G.accent2} radius={[4,4,0,0]} name="Expenses" />
              <Bar dataKey="income"   fill={G.green}   radius={[4,4,0,0]} name="Income" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div style={s.card}>
          <div style={s.cardTitle}>🍕 Category Breakdown</div>
          {catData.length === 0
            ? <div style={{ color: G.muted, fontSize: 13, textAlign: "center", paddingTop: 60 }}>No expenses this month yet</div>
            : <ResponsiveContainer width="100%" height={200}>
                <PieChart>
                  <Pie data={catData} dataKey="total" nameKey="category" cx="50%" cy="50%" innerRadius={50} outerRadius={75} paddingAngle={3}>
                    {catData.map((_, i) => <Cell key={i} fill={CAT_COLORS[i % CAT_COLORS.length]} />)}
                  </Pie>
                  <Tooltip {...tooltipStyle} formatter={v => fmt(v)} />
                  <Legend iconType="circle" wrapperStyle={{ fontSize: 11, color: G.muted }} />
                </PieChart>
              </ResponsiveContainer>
          }
        </div>
      </div>

      {/* Quick Add */}
      <div style={s.card}>
        <div style={s.cardTitle}>➕ Quick Add Transaction</div>
        <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr auto", gap: 10, alignItems: "end" }}>
          <div>
            <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Description</div>
            <input style={s.input} placeholder="e.g. Lunch" value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
          </div>
          <div>
            <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Amount ₹</div>
            <input style={s.input} type="number" placeholder="0" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} />
          </div>
          <div>
            <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Category</div>
            <select style={s.select} value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
              {CATEGORIES.map(c => <option key={c}>{c}</option>)}
            </select>
          </div>
          <div>
            <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Type</div>
            <select style={s.select} value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value }))}>
              <option value="expense">Expense</option>
              <option value="income">Income</option>
            </select>
          </div>
          <div>
            <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Date</div>
            <input style={s.input} type="date" value={form.date} onChange={e => setForm(f => ({ ...f, date: e.target.value }))} />
          </div>
          <button style={s.addBtn} onClick={addTxn} disabled={saving}>
            {saving ? "..." : "Add"}
          </button>
        </div>
        {msg && <div style={{ marginTop: 10, fontSize: 13, color: msg.startsWith("✅") ? G.green : G.red }}>{msg}</div>}
      </div>
    </div>
  );
}
